//! Report account balances from a ledger file.

use std::collections::HashMap;
use std::env;
use std::fs;

/// Converts an amount such as `12.05` into cents.
fn to_cents(amount: &str) -> i64 {
    let (whole, fraction) = amount.split_once('.').expect("an amount with two fraction digits");
    let whole: i64 = whole.parse().expect("a whole-number part");
    let fraction: i64 = fraction.parse().expect("two fraction digits");
    whole * 100 + fraction
}

fn format_cents(cents: i64) -> String {
    let sign = if cents < 0 { "-" } else { "" };
    let cents = cents.abs();
    format!("{}{}.{:02}", sign, cents / 100, cents % 100)
}

fn read_ledger(path: &str) -> String {
    fs::read_to_string(path).expect("a readable ledger")
}

fn main() {
    let path = env::args().nth(1).expect("a ledger path");
    let text = read_ledger(&path);
    let mut lines = text.lines();
    let header = lines.next().unwrap_or("ledger 0");
    let n: usize = header
        .split_whitespace()
        .nth(1)
        .unwrap_or("0")
        .parse()
        .expect("a transaction count");

    let mut balances: HashMap<String, i64> = HashMap::new();
    for (index, line) in lines.take(n).enumerate() {
        let fields: Vec<&str> = line.split_whitespace().collect();
        let (account, kind, amount) = (fields[0], fields[1], fields[2]);
        let amount_cents = to_cents(amount);
        let signed = match kind {
            "credit" => amount_cents,
            "debit" => -amount_cents,
            _ => {
                println!("ERROR line {}", index + 1);
                return;
            }
        };
        *balances.entry(account.to_string()).or_insert(0) += signed;
    }

    let mut entries: Vec<(String, i64)> = balances.into_iter().collect();
    entries.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    let mut total = 0;
    for (account, balance) in &entries {
        println!("{} {}", account, format_cents(*balance));
        total += balance;
    }
    println!("TOTAL {}", format_cents(total));
}

